{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='GET' AND attr_span_kind='Client' GROUP BY 1",
          "claim": "In the incident, all of preserve's outgoing GET client calls return 404; normal period had 200s."
        },
        {
          "kind": "log",
          "sql": "SELECT message FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' LIMIT 5",
          "claim": "Preserve's SEVERE logs show its downstream 404 response body with path \"/api/v2/\", meaning the request path was rewritten."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='ts-security-service' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Security served 1603 'GET /**' requests as 404 in the incident, versus 131 successful securityConfigs GETs in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY 1,2",
          "claim": "Preserve's preserve endpoint returns 500 on all 1603 abnormal requests; normal was 200 with about 356 ms mean latency."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT u.attr_http_response_status_code code, count(p.span_id) n_children, round(u.duration/1e6,0) ui_ms FROM abnormal_traces u LEFT JOIN abnormal_traces p ON p.parent_span_id=u.span_id AND p.service_name='ts-preserve-service' AND p.attr_span_kind='Server' WHERE u.service_name='ts-ui-dashboard' AND u.span_name LIKE '%preserve%' GROUP BY u.span_id, u.attr_http_response_status_code, u.duration ORDER BY ui_ms DESC LIMIT 15",
          "claim": "ui-dashboard's preserve requests make about 16 retried calls to preserve, each returning 500, inflating user latency to several seconds."
        }
      ]
    }
  ]
}

